export class TestScenarioRunner {
  public activeScenario: TestScenario | null = null;
  public scenarios: TestScenario[] = [];
  private scenarioTimer = 0;
  private peakValue = 0;
  private initialAlt = 0;

  constructor() {
    this.scenarios = this.initScenarios();
  }

  private initScenarios(): TestScenario[] {
    return [
      {
        id: 'FAT-01',
        name: 'Maiden Hover & Attitude Stability',
        category: 'STABILITY',
        description: 'Verifies 5-meter hover hold, attitude leveling variance, and RMS vibration limits.',
        estimatedDurationSec: 8,
        status: 'IDLE',
        progressPercent: 0,
        criteria: [
          { id: 'c1', name: 'Altitude Hold Variance', metric: 'variance', target: 0.35, measured: 0, tolerance: 0.1, unit: 'm', passed: false },
          { id: 'c2', name: 'Roll/Pitch Bank StdDev', metric: 'bank_std', target: 0.05, measured: 0, tolerance: 0.02, unit: 'rad', passed: false },
          { id: 'c3', name: 'Max G-Force During Hover', metric: 'g_force', target: 1.15, measured: 0, tolerance: 0.1, unit: 'g', passed: false },
        ],
      },
      {
        id: 'FAT-02',
        name: 'Vertical Step Response (15m Climb)',
        category: 'AERODYNAMICS',
        description: 'Executes rapid 15m step altitude command; measures rise time and overshoot percentage.',
        estimatedDurationSec: 10,
        status: 'IDLE',
        progressPercent: 0,
        criteria: [
          { id: 'c4', name: 'Overshoot Percentage', metric: 'overshoot', target: 8.0, measured: 0, tolerance: 3.0, unit: '%', passed: false },
          { id: 'c5', name: 'Climb Rate Peak', metric: 'peak_vy', target: 3.0, measured: 0, tolerance: 0.5, unit: 'm/s', passed: false },
        ],
      },
      {
        id: 'FAT-03',
        name: 'Wind Gust Disturbance Rejection',
        category: 'AERODYNAMICS',
        description: 'Simulates violent 14 m/s crosswind gust; evaluates PID restoration & maximum drift.',
        estimatedDurationSec: 9,
        status: 'IDLE',
        progressPercent: 0,
        criteria: [
          { id: 'c6', name: 'Max Horizontal Drift', metric: 'drift', target: 2.5, measured: 0, tolerance: 0.8, unit: 'm', passed: false },
          { id: 'c7', name: 'Recovery Time to <0.5m', metric: 'recovery_time', target: 3.5, measured: 0, tolerance: 1.0, unit: 's', passed: false },
        ],
      },
      {
        id: 'FAT-04',
        name: 'Rotor Loss & Degradation Recovery',
        category: 'FAILSAFE',
        description: 'Degrades Motor #3 thrust to 35%; evaluates multirotor attitude stability & controlled RTL.',
        estimatedDurationSec: 10,
        status: 'IDLE',
        progressPercent: 0,
        criteria: [
          { id: 'c8', name: 'Attitude Inversion Prevention', metric: 'max_roll', target: 0.35, measured: 0, tolerance: 0.1, unit: 'rad', passed: false },
          { id: 'c9', name: 'Descent Rate Containment', metric: 'descent_rate', target: 2.5, measured: 0, tolerance: 0.5, unit: 'm/s', passed: false },
        ],
      },
      {
        id: 'FAT-05',
        name: 'Geofence Breach & Autonomous RTL',
        category: 'AUTONOMY',
        description: 'Navigates beyond 40m geofence perimeter; verifies failsafe RTL trigger, climb & auto-land.',
        estimatedDurationSec: 12,
        status: 'IDLE',
        progressPercent: 0,
        criteria: [
          { id: 'c10', name: 'RTL Mode Trigger Latency', metric: 'trigger_time', target: 1.0, measured: 0, tolerance: 0.4, unit: 's', passed: false },
          { id: 'c11', name: 'Home Landing Accuracy', metric: 'home_dist', target: 1.8, measured: 0, tolerance: 0.7, unit: 'm', passed: false },
